unsigned long scaled_total(unsigned long pulses, unsigned long scale, unsigned long total) {
    return total + pulses * scale;
}

unsigned long consumption(unsigned long fuel, unsigned long distance) {
    if (distance == 0) return 0;
    return fuel * 100UL / distance;
}

unsigned long half_distance(unsigned long distance) {
    return distance >> 1;
}
unsigned long report(unsigned long distance) {
    return half_distance(distance) + 3;
}

unsigned long fade_sum(unsigned long brightness) {
    if (brightness == 0) return 0;
    return brightness + fade_sum(brightness >> 1);
}
